/* Northern Response: browser-local exercise console. No real dispatch or clinical system. */
(function () {
  'use strict';
  var S = NORTHERN_RESPONSE;
  var PREFIX = 'nr-ttx-v1:', INDEX = PREFIX + 'sessions', ACTIVE = PREFIX + 'active', DISPLAY = PREFIX + 'display';
  var view = 'control', selectedInject = null, categoryFilter = '', patientSearch = '', toastTimer;
  var storageOK = true, sessionList, state;
  var facilityNames=['Rendezvous Point (RVP)','Staging Area (SA)','Mobile Command Post (MCP)','Triage Area (TA)','Casualty Collection Area (CCA)','Casualty Clearance Station (CCS)','Ambulance loading point','Survivor Assembly Area (SAA)','AEMC','Survivor Reception Centre (SRC)','Friends and Relatives Reception Centre (FRRC)','Crew Reception Centre (CRC)','Reunion Centre (RC)','Media Centre','Temporary mortuary'];
  var facilityReference=['AEP §11.14: airside / landside security check post; Aviation Security Command coordinates RVP access.','AEP §11.12: Hangar Apron; Ramp Services establishes and manages staging.','AEP §11.2: ARFF deploys MCP; incident-dependent, upwind, risk-assessed positioning under IC discretion.','AEP §11.3: safe, upwind triage position; ARFF initially, then designated Medical Coordinator and IC.','AEP §11.4: ARFF establishes CCA; jointly managed with medical personnel.','AEP §11.6: Ramp Services initially establishes CCS; formal handover to ARFF working with the medical team.','Confirm safe loading access and the patient-handover route with IC and Medical Coordinator.','AEP §11.5: temporary survivor holding near the site; assessed minor casualties may use SAA before SRC.','AEP §11.1 and §8.2.1: Fire Station first floor; Airport Manager or designee chairs Gold coordination.','AEP §11.7: terminal boarding gate area; Passenger Services and airline, with Police security; excludes crew.','AEP §11.8: Jetty Terminal Building; Passenger Services and airline, with Police security.','AEP §11.9: Fire Station fourth floor; Passenger Services and airline, with Police security.','AEP §11.10: Hanimaadhoo Social Center; Passenger Services and airline with Island Council assistance.','AEP §11.15: Headquarters; Media Liaison Officer coordinates approvals.','Appendix 1: fatalities and evidence remain subject to the authorised Police/investigation process; confirm arrangement.'];
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };
  var uid = function () { return typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2); };
  var now = function () { return new Date().toISOString(); };
  var mvtDate = function () { return new Intl.DateTimeFormat('en-CA', {timeZone:'Indian/Maldives',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()); };
  var read = function (key, fallback) { try { return JSON.parse(localStorage.getItem(key)) || fallback; } catch (_) { return fallback; } };
  var put = function (key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch (_) { storageOK = false; if ($('saveStatus')) $('saveStatus').textContent = 'Storage unavailable · export a backup'; return false; } };
  var dateLabel = function (d) { return d ? d.split('-').reverse().join('/') : 'Date not set'; };
  var scenarioTime = function (ms) { var sec = Math.floor((S.startMinute * 60000 + ms) / 1000); return [Math.floor(sec / 3600) % 24,Math.floor(sec / 60) % 60,sec % 60].map(function(n){return String(n).padStart(2,'0');}).join(':'); };
  var elapsed = function () { return state.elapsed + (state.running ? Math.max(0,Date.now() - state.anchor) * state.speed : 0); };
  var clockText = function (ms) { return scenarioTime(ms).slice(0,5); };
  var audit = function (type, detail) { state.audit.push({id:uid(),at:now(),scenario:scenarioTime(elapsed()),type:type,detail:detail}); };
  var toast = function (message) { clearTimeout(toastTimer); $('toast').textContent=message; $('toast').hidden=false; toastTimer=setTimeout(function(){ $('toast').hidden=true; },4500); };

  function fresh(name, date, facilitator) {
    var patients=[];
    S.categories.forEach(function(c){for(var n=1;n<=c.count;n++)patients.push({id:c.prefix+String(n).padStart(2,'0'),category:c.id,status:'Unlocated',location:'',destination:'',accepted:false,transport:'',notes:'',updatedAt:null});});
    return {schema:1,scenarioId:S.id,id:uid(),name:name,date:date,facilitator:facilitator||'',createdAt:now(),updatedAt:now(),elapsed:0,anchor:null,running:false,speed:1,ended:false,pausedForSafety:false,released:[],patients:patients,decisions:[],resources:[],actions:[],commandTransfers:[],facilities:facilityNames.map(function(n){return {name:n,status:'Not established',owner:'',location:''};}),review:S.objectives.map(function(){return {score:-1,evidence:''};}),audit:[],revision:0};
  }
  function listSession() {
    var summary={id:state.id,name:state.name,date:state.date,updatedAt:state.updatedAt};
    var pos=sessionList.findIndex(function(x){return x.id===state.id;});
    if(pos<0)sessionList.unshift(summary);else sessionList[pos]=summary;
    put(INDEX,sessionList);
  }
  function save() {
    state.updatedAt=now();state.revision++;
    if(put(PREFIX+state.id,state)){if(storageOK)$('saveStatus').textContent='Saved on this device';}
    listSession();put(ACTIVE,state.id);publish();
  }
  function pause() { state.elapsed=elapsed();state.running=false;state.anchor=null; }
  function publish() {
    // Only explicitly released material goes into the projector payload.
    var released=state.released.map(function(r){return {at:S.injects[r.index].at,title:S.injects[r.index].title,from:S.injects[r.index].from,phase:S.injects[r.index].phase,message:S.injects[r.index].message,prompt:S.injects[r.index].prompt};});
    put(DISPLAY,{schema:1,sessionId:state.id,durationMinutes:S.durationMinutes,name:state.name,date:state.date,elapsed:elapsed(),running:state.running,ended:state.ended,pausedForSafety:state.pausedForSafety,updatedAt:now(),released:released,casualties:state.released.some(function(r){return r.index===6;})?S.categories.map(function(c){return {category:c.id,count:c.count,label:c.label};}):null});
  }
  function isUnlocked() {return state.released.some(function(r){return r.index===6;});}
  function confirmAction(title, message, callback) {
    $('confirmTitle').textContent=title;$('confirmText').textContent=message;
    var dialog=$('confirmDialog');dialog.returnValue='';dialog.onclose=function(){if(dialog.returnValue==='confirm')callback();};dialog.showModal();
  }
  function openNewSession() {$('newSessionForm').elements.date.value=mvtDate();$('newSessionDialog').showModal();}

  function heading(label, title, subtitle) {return '<div class="page-heading"><div><span class="eyebrow">'+esc(label)+'</span><h1>'+esc(title)+'</h1><p>'+esc(subtitle)+'</p></div><span class="session-chip">'+(state.ended?'SESSION ENDED':state.running?'CLOCK RUNNING':'FACILITATOR VIEW')+'</span></div>';}
  function totals() {return '<div class="casualty-totals">'+S.categories.map(function(c){return '<div class="stat '+c.id.toLowerCase()+'"><span class="eyebrow">'+esc(c.id)+'</span><span class="number">'+c.count+'</span><small>'+esc(c.label)+(c.id==='Red'?' · 20% of POB':'')+'</small></div>';}).join('')+'</div>';}
  function clock() {return '<section class="clock-strip" aria-label="Exercise clock"><div><span class="eyebrow">SCENARIO TIME · MALDIVES</span><div class="clock"><span id="clockValue">'+scenarioTime(elapsed())+'</span><small>MVT · UTC+5</small></div><div class="clock-detail" id="clockDetail"></div></div><div class="clock-controls"><button type="button" id="playBtn" '+(state.ended||state.pausedForSafety?'disabled':'')+'>'+ (state.running?'Pause clock':'Start clock')+'</button><button type="button" id="advanceBtn" '+(state.ended||state.pausedForSafety?'disabled':'')+'>+1 min</button><button type="button" id="resetExerciseBtn" title="Restart the current exercise and clear its run records">Reset exercise</button><select id="speedSelect" aria-label="Clock speed" '+(state.ended||state.pausedForSafety?'disabled':'')+'>'+[1,2,5,10].map(function(n){return '<option value="'+n+'" '+(state.speed===n?'selected':'')+'>'+n+'×</option>';}).join('')+'</select><button type="button" id="nextBtn" class="primary" '+(state.released.length===S.injects.length||state.ended||state.pausedForSafety?'disabled':'')+'>'+(state.released.length?'Release next inject':'Begin · release ATC call')+'</button></div></section>';}
  function currentCard() {
    var r=selectedInject===null ? state.released[state.released.length-1] : state.released.find(function(x){return x.index===selectedInject;});
    if(!r)return '<section class="panel current-event"><span class="eyebrow">READY WHEN YOU ARE</span><div class="empty-state"><h2>Ten minutes to prepare.<br>A response to coordinate.</h2><p>An A320 is approaching Hanimaadhoo with a landing gear emergency. Your team must turn the warning into a coordinated response.</p><p class="muted">Brief players first. Release the ATC call to begin at 16:00. Injects are released manually; releasing a future inject advances scenario time.</p><button type="button" data-goto="setup">Read participant brief →</button></div></section>';
    var inj=S.injects[r.index];
    return '<section class="panel current-event"><div class="event-meta"><span class="tag">RELEASED INJECT '+(r.index+1)+'</span><span class="event-time">'+clockText(inj.at*60000)+' MVT</span><span>'+esc(inj.from)+' · '+esc(inj.phase)+'</span></div><h2>'+esc(inj.title)+'</h2><p class="message">'+esc(inj.message)+'</p><div class="event-prompt"><span class="eyebrow">DISCUSS & DECIDE</span><p>'+esc(inj.prompt)+'</p></div><details><summary>Facilitator notes · keep off the projector</summary><p>'+esc(inj.expected)+'</p></details><button type="button" class="wide" data-goto="decisions">Record the team’s decision →</button></section>';
  }
  function injectList() {
    return '<section class="panel"><div class="panel-header"><h2>Inject sequence</h2><span class="count-badge">'+state.released.length+' / '+S.injects.length+'</span></div><div class="timeline-list">'+S.injects.map(function(inj,i){var rel=state.released.some(function(r){return r.index===i;});return '<div class="inject-row '+(rel?'released':'')+' '+((selectedInject===i||(selectedInject===null&&i===state.released.length-1))?'selected':'')+'"><time>'+clockText(inj.at*60000)+'</time><div><strong>'+esc(inj.title)+'</strong><small>'+esc(inj.from)+'</small></div>'+(rel?'<button type="button" data-inject="'+i+'">View</button>':'<small>'+(i===state.released.length?'NEXT':'QUEUED')+'</small>')+'</div>';}).join('')+'</div><p class="prompt-note">Controller sequence only. The projector receives released messages and discussion prompts.</p></section>';
  }
  function flow() {
    return '<section class="panel"><div class="panel-header"><h2>Response priorities</h2><span class="eyebrow">SCHEMATIC</span></div><svg class="flow-diagram" viewBox="0 0 400 210" role="img" aria-label="ARFF-coordinated rescue flows through medical-led triage and treatment to confirmed transport and handover"><path d="M200 52V76M200 126V150" stroke="#627b88" stroke-width="2" stroke-dasharray="4 4"/><rect x="20" y="1" width="360" height="51" rx="7" fill="#352d30" stroke="#6b4b47"/><text x="200" y="23" text-anchor="middle" fill="#edb9a1" font-size="12">01 · SAFE RESCUE</text><text x="200" y="40" text-anchor="middle" fill="#b8a5a3" font-size="10">Coordinate with ARFF · control access</text><rect x="20" y="76" width="360" height="51" rx="7" fill="#24332d" stroke="#43594d"/><text x="200" y="98" text-anchor="middle" fill="#b9d0b6" font-size="12">02 · TRIAGE & TREATMENT</text><text x="200" y="115" text-anchor="middle" fill="#9aad9f" font-size="10">Medical-led priorities · track every person</text><rect x="20" y="151" width="360" height="51" rx="7" fill="#203441" stroke="#3d5869"/><text x="200" y="173" text-anchor="middle" fill="#b7d0de" font-size="12">03 · MOVEMENT & HANDOVER</text><text x="200" y="190" text-anchor="middle" fill="#9aafbd" font-size="10">Confirmed transport · receiving acceptance</text></svg><p class="flow-caption">Use the approved airport map for actual positions, access gates and safe casualty areas.</p></section>';
  }
  function renderControl() {
    var patientInfo=isUnlocked()?totals():'<div class="note-box">Casualty totals are withheld from the projector until the medical assessment at 16:18. Controller planning allocation: 22 red, 33 yellow, 50 green, 5 deceased.</div>';
    return heading('LIVE EXERCISE / '+dateLabel(state.date),'Control room',state.name+' · '+(state.facilitator||'Facilitator not assigned'))+(state.ended?'<div class="end-banner">Exercise ended. Records remain available for review and export. Start a new session to run again.</div>':'')+clock()+'<div class="grid-two"><div class="stack">'+currentCard()+injectList()+'</div><div class="stack"><section class="panel"><div class="panel-header"><h2>People on board</h2><span class="count-badge">110 TOTAL</span></div>'+patientInfo+'<div class="event-meta"><span>104 passengers + 6 crew</span><span>Fictional flight EXR320</span></div><button type="button" class="wide" data-goto="casualties">Open casualty board →</button></section>'+flow()+'<section class="panel"><h2>Exercise snapshot</h2><ul class="mini-list"><li><strong>'+state.decisions.filter(function(d){return d.status==='Open';}).length+' open decisions</strong><p>Every decision needs an owner and a next action.</p></li><li><strong>'+state.resources.filter(function(r){return r.status==='Assigned';}).length+' assigned resource tasks</strong><p>Capabilities and availability must be confirmed.</p></li><li><strong>'+state.actions.filter(function(a){return a.status==='Open';}).length+' review actions</strong><p>Capture improvements while the discussion is fresh.</p></li></ul><button type="button" id="endBtn" class="wide" '+(state.ended||state.pausedForSafety?'disabled':'')+'>End exercise & debrief</button></section></div></div>';
  }
  var patientStatuses=['Unlocated','Located','Treatment','In transfer','Handed over','Deceased holding'];
  function matchingPatients(){return state.patients.filter(function(p){return (!categoryFilter||p.category===categoryFilter)&&(!patientSearch||(p.id+' '+p.location+' '+p.destination).toLowerCase().includes(patientSearch.toLowerCase()));});}
  function patientRows(){return matchingPatients().map(function(p){return '<tr><td><input type="checkbox" name="patientPick" value="'+p.id+'" aria-label="Select '+p.id+'"></td><td><b>'+p.id+'</b></td><td><span class="pill '+p.category.toLowerCase()+'">'+p.category+'</span></td><td>'+esc(p.status)+'<p>'+esc(p.location||'Location not recorded')+'</p></td><td>'+esc(p.destination||'—')+'<p>'+esc(p.transport)+(p.accepted?' · accepted':'')+'</p></td><td><button type="button" data-patient="'+p.id+'">Update</button></td></tr>';}).join('');}
  function renderCasualties(){
    if(!isUnlocked())return heading('PATIENT ACCOUNTABILITY','Casualty board','22 red patients = 20% of 110 persons aboard.')+'<section class="panel"><h2>Awaiting the medical assessment</h2><p>Release the 16:18 medical inject before opening the simulated patient register. Categories are scenario inputs. Clinical reassessment stays with the medical lead.</p><button type="button" data-goto="control">Return to control room</button></section>';
    var located=state.patients.filter(function(p){return p.status!=='Unlocated';}).length, handed=state.patients.filter(function(p){return p.status==='Handed over';}).length;
    return heading('PATIENT ACCOUNTABILITY','Casualty board','Simulated patient IDs only. Record location and movement; use medical-led priorities.')+totals()+'<div class="accounting '+(located<110?'warning':'')+'"><div><strong>'+located+' / 110 location records completed</strong><p>Categories total 110. A category is not proof that the person’s location has been recorded.</p></div><span class="count-badge">'+handed+' handed over</span></div><section class="panel"><div class="panel-header"><h2>Patient register</h2><button type="button" id="bulkPatientBtn">Update selected</button></div><div class="filter-bar"><label>Priority<select id="categoryFilter"><option value="">All categories</option>'+S.categories.map(function(c){return '<option '+(categoryFilter===c.id?'selected':'')+'>'+c.id+'</option>';}).join('')+'</select></label><label>Search ID, location or destination<input id="patientSearch" value="'+esc(patientSearch)+'" placeholder="e.g. R01"></label><button type="button" id="selectFilteredBtn">Select filtered</button></div><div class="table-wrap"><table><thead><tr><th scope="col">Select</th><th scope="col">Patient</th><th scope="col">Priority</th><th scope="col">Status / location</th><th scope="col">Destination / transport</th><th scope="col">Action</th></tr></thead><tbody id="patientRows">'+patientRows()+'</tbody></table></div><p class="prompt-note">Six trapped casualties are included within the 22 red. “In transfer” and “Handed over” require confirmed receiving acceptance, a destination and a transport identifier. Deceased records use the authorised exercise process.</p></section>';
  }
  function options(values,selected){return values.map(function(v){return '<option '+(v===selected?'selected':'')+'>'+esc(v)+'</option>';}).join('');}
  function patientDialog(ids){
    if(!ids.length){toast('Select at least one patient.');return;}
    var patients=state.patients.filter(function(p){return ids.includes(p.id);}),p=patients[0];
    var d=document.createElement('dialog');d.id='patientDialog';
    d.innerHTML='<form id="patientForm"><div class="dialog-heading"><h2>Update '+(ids.length===1?esc(ids[0]):ids.length+' patients')+'</h2><button type="button" data-close="patientDialog" aria-label="Close patient update">×</button></div><p class="muted">'+esc(ids.join(', '))+'</p><label>Status<select name="status">'+options(patientStatuses,ids.length===1?p.status:'Located')+'</select></label><label>Current location<input name="location" required maxlength="120" value="'+esc(ids.length===1?p.location:'')+'" placeholder="AEP casualty area / receiving facility"></label><div class="form-grid"><label>Receiving destination<input name="destination" maxlength="120" value="'+esc(ids.length===1?p.destination:'')+'"></label><label>Transport identifier<input name="transport" maxlength="100" value="'+esc(ids.length===1?p.transport:'')+'"></label></div><label><input name="accepted" type="checkbox" '+(ids.length===1&&p.accepted?'checked':'')+'>Receiving acceptance confirmed in the exercise</label><label>Movement / handover notes<textarea name="notes" maxlength="2000">'+esc(ids.length===1?p.notes:'')+'</textarea></label><p class="field-error" id="patientError" role="alert"></p><p class="muted">This replaces the selected records’ movement fields. Priority allocation remains fixed for this exercise.</p><button class="primary wide">Save movement records</button></form>';
    document.body.appendChild(d);d.addEventListener('close',function(){d.remove();});d.showModal();
    $('patientForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),status=f.get('status'),location=String(f.get('location')).trim(),destination=String(f.get('destination')).trim(),transport=String(f.get('transport')).trim(),accepted=f.has('accepted');
      if(!location){$('patientError').textContent='Enter the current location.';return;}
      if((status==='In transfer'||status==='Handed over')&&(!accepted||!destination||!transport)){$('patientError').textContent='Confirm receiving acceptance, destination and transport before recording a transfer or handover.';return;}
      if(patients.some(function(x){return x.category==='Deceased';})&&['Treatment','In transfer','Handed over'].includes(status)){$('patientError').textContent='Use Located or Deceased holding for deceased records, with authorised process details in the notes.';return;}
      if(patients.some(function(x){return x.category!=='Deceased';})&&status==='Deceased holding'){$('patientError').textContent='Deceased holding applies only to the five scenario fatality records.';return;}
      patients.forEach(function(x){Object.assign(x,{status:status,location:location,destination:destination,transport:transport,accepted:accepted,notes:String(f.get('notes')).trim(),updatedAt:now()});});
      audit('Casualty movement',ids.join(', ')+': '+status+' · '+location);save();d.close();render();toast('Patient records updated.');
    };
  }
  function renderResources(){return heading('CAPABILITIES & COORDINATION','Resources & tasks','Record exercise requests. No responding agency units, strengths, locations or response times are prefilled.')+'<div class="grid-two"><section class="panel"><h2>Resource task board</h2><div class="table-wrap"><table><thead><tr><th>Capability / owner</th><th>Quantity</th><th>Status</th><th>ETA · MVT</th><th>Action</th></tr></thead><tbody>'+state.resources.map(function(r){return '<tr><td><b>'+esc(r.capability)+'</b><p>'+esc(r.owner)+'</p><p>'+esc(r.notes)+'</p></td><td>'+r.quantity+'</td><td>'+esc(r.status)+'<p>'+(r.confirmed?'Availability confirmed':'Availability unconfirmed')+'</p></td><td>'+esc(r.eta||'Unconfirmed')+'</td><td><button type="button" data-resource="'+r.id+'">Edit</button></td></tr>';}).join('')+'</tbody></table></div>'+(!state.resources.length?'<p class="empty-small">No resource requests yet. Establish needs and confirm capabilities with agency representatives.</p>':'')+'</section><section class="panel"><h2 id="resourceFormTitle">Add a resource task</h2><form id="resourceForm"><input type="hidden" name="id"><label>Capability required<input name="capability" required maxlength="120" placeholder="e.g. Medical transport"></label><div class="form-grid"><label>Quantity<input name="quantity" type="number" value="1" min="1" max="10000" required></label><label>ETA · MVT<input name="eta" type="time"></label></div><label>Responsible appointment / agency<input name="owner" required maxlength="120"></label><label>Status<select name="status">'+options(['Requested','Available','Assigned','Released','Unavailable'],'Requested')+'</select></label><label><input name="confirmed" type="checkbox">Availability and capability confirmed</label><label>Task, constraints and confirmation details<textarea name="notes" maxlength="3000" placeholder="Include receiving acceptance and clinical suitability when requesting transport."></textarea></label><p class="field-error" id="resourceError" role="alert"></p><button class="primary wide">Save resource task</button></form><div class="note-box">Coordinate through the AEP. An assigned task needs confirmed availability. Boats and aircraft are not automatically suitable for patient transport.</div></section></div>';}
  function renderDecisions(){return heading('COMMAND RECORD','Decision log','Capture the decision, its owner and next action at the current scenario time.')+'<div class="grid-two"><section class="panel"><div class="panel-header"><h2>Recorded decisions</h2><span class="count-badge">'+state.decisions.length+'</span></div>'+(!state.decisions.length?'<p class="empty-small">No decisions recorded yet. Start with notification, command and initial mobilisation.</p>':'<div class="table-wrap"><table><thead><tr><th>Time · MVT</th><th>Decision / next action</th><th>Owner</th><th>Status</th></tr></thead><tbody>'+state.decisions.slice().reverse().map(function(d){return '<tr><td>'+esc(d.scenario)+'</td><td><b>'+esc(d.text)+'</b><p>'+esc(d.action)+'</p><p>Review: '+esc(d.due||'Not set')+' · '+esc(d.inject||'General')+'</p></td><td>'+esc(d.owner)+'</td><td><button type="button" data-decision="'+d.id+'">'+esc(d.status)+'</button></td></tr>';}).join('')+'</tbody></table></div>')+'<p class="prompt-note">Select a status to close or reopen a decision. Every change is retained in the audit record.</p></section><section class="panel"><h2>Record a decision</h2><form id="decisionForm"><label>Decision<textarea name="text" required maxlength="4000" placeholder="What did the team decide, and why?"></textarea></label><label>Responsible appointment<input name="owner" required maxlength="120"></label><label>Next action<textarea name="action" required maxlength="2000"></textarea></label><label>Review / due time · MVT<input name="due" type="time"></label><button class="primary wide">Record decision</button></form></section></div>';}
  function renderReview(){var rated=state.review.filter(function(r){return r.score>=0;}),score=rated.reduce(function(n,r){return n+r.score;},0);return heading('OBSERVE / LEARN / IMPROVE','After-action review','Score discussion evidence. A tabletop does not certify practical response performance.')+'<div class="grid-two"><section class="panel"><div class="panel-header"><h2>Exercise objectives</h2><span class="review-score" id="reviewScore">'+score+' / 12</span></div><p class="muted" id="ratedCount">'+rated.length+' of 6 objectives assessed · 0 = not addressed; 1 = incomplete; 2 = clear, feasible decision with owner.</p>'+S.objectives.map(function(o,i){return '<div class="review-card"><h3>'+String(i+1).padStart(2,'0')+' · '+esc(o[0])+'</h3><p>'+esc(o[1])+'</p><label>Assessment<select data-score="'+i+'">'+[[-1,'Not assessed'],[0,'0 — Not addressed'],[1,'1 — Incomplete'],[2,'2 — Clear decision and owner']].map(function(v){return '<option value="'+v[0]+'" '+(state.review[i].score===v[0]?'selected':'')+'>'+v[1]+'</option>';}).join('')+'</select></label><label>Observed evidence / gap<textarea data-evidence="'+i+'" maxlength="4000">'+esc(state.review[i].evidence)+'</textarea></label></div>';}).join('')+'</section><div class="stack"><section class="panel"><h2>Improvement actions</h2>'+state.actions.map(function(a){return '<div class="review-card"><h3>'+esc(a.text)+'</h3><p>Owner: '+esc(a.owner)+' · Due: '+dateLabel(a.due)+'</p><button type="button" data-action="'+a.id+'">'+esc(a.status)+'</button></div>';}).join('')+(!state.actions.length?'<p class="empty-small">Capture gaps with an owner and due date.</p>':'')+'<div class="section-rule"></div><form id="actionForm"><label>Corrective action<textarea name="text" required maxlength="3000"></textarea></label><label>Owner<input name="owner" required maxlength="120"></label><label>Due date<input name="due" type="date" required></label><button class="primary wide">Add improvement action</button></form></section><section class="panel"><h2>Hotwash prompts</h2><ul class="checklist"><li>What worked in the first ten minutes?</li><li>Which decisions lacked authority or information?</li><li>What delayed support for the 22 red patients?</li><li>Where did inter-agency handovers break down?</li><li>Which three changes are needed before a practical exercise?</li></ul><button type="button" id="reviewExportBtn" class="wide">Export report & backup</button></section></div></div>';}
  function renderSetup(){return heading('EXERCISE DIRECTOR','Brief & sessions','A facilitated multi-agency discussion, supported by simulated partner agencies.')+'<div class="setup-columns"><div class="stack"><section class="panel"><span class="eyebrow">PARTICIPANT BRIEF</span><h2 style="margin-top:12px">Hanimaadhoo · 16:00 MVT</h2><p>An Airbus A320, fictional flight EXR320, is approaching Hanimaadhoo International Airport with 110 persons aboard. At 16:00, ATC receives a landing gear failure report. The captain declares an emergency and estimates landing at 16:10.</p><p>The exercise will test responder mobilisation, formal assumption of incident command from ARFF, AEMC coordination, safe rescue support, casualty movement, reinforcement, sustainment and handover. HAQ AEP §8.3.1 assigns on-scene command to the designated Incident Commander after ARFF interim command.</p><div class="note-box">Start by stating your first actions, authority, resources and information needs. Coordinate with airport operations, ATC, ARFF, police and health services through the approved AEP.</div><h3>Total session · '+S.durationMinutes+' minutes</h3><ul class="checklist">'+S.delivery.map(function(item){return '<li>'+item.minutes+' minutes — '+esc(item.activity)+'</li>';}).join('')+'</ul><p class="muted">Scenario time is independent of real time. Start/pause the clock, change speed, advance one minute, or manually release the next inject. Future inject release advances the clock when necessary; the clock never releases injects automatically.</p></section><section class="panel"><h2>Facilitator preparation</h2><ul class="checklist"><li>Assign incident command, operations, liaison, logistics, medical liaison, communications and accountability roles.</li><li>Have controllers represent airport operations, ATC, ARFF, police, health services, airline and relevant civil authorities.</li><li>Obtain the current AEP and verified airport grid map. Confirm gates, staging, command arrangements and communications.</li><li>Confirm actual resource capabilities, receiving medical capacity and transport arrangements. No default availability is assumed.</li><li>All calls and messages are simulated. Pause for any real emergency and use actual emergency procedures.</li></ul><details><summary>Controller scenario assumptions & casualty allocation</summary><p>The crash occurs at 16:10 on airport land, partly off the paved surface. The left engine catches fire. 104 passengers and 6 crew total 110. There are 22 red, 33 yellow, 50 green and 5 deceased. Six trapped persons are included within the red allocation. Red patient cues: 6 severe burns/suspected inhalation injury; 8 major trauma; 4 crush/lower-limb injury; 2 head injury; 2 children with serious trauma. These are discussion cues for qualified medical personnel.</p></details><p class="muted">Airport identifier VRMH: <a href="https://caa.gov.mv/operations/air-operations/status-of-certification-of-aerodromes" target="_blank" rel="noopener">Maldives CAA</a>. General exercise planning: <a href="https://www.icao.int/emergency-response-planning" target="_blank" rel="noopener">ICAO</a>. All scenario timings and casualty numbers are exercise inputs. Primary reference: supplied HAQ AEP Edition 2, effective 15 Nov 2025. Its command and facility provisions take precedence over the HDK briefing. See Command & facilities for section references. Current local AEP, responding agency orders and clinical protocols govern real operations.</p></section></div><div class="stack"><section class="panel"><h2>Current session</h2><form id="settingsForm"><label>Exercise name<input name="name" required maxlength="100" value="'+esc(state.name)+'"></label><label>Exercise date · MVT<input name="date" type="date" required value="'+esc(state.date)+'"></label><label>Facilitator<input name="facilitator" maxlength="100" value="'+esc(state.facilitator)+'"></label><button class="wide">Save session details</button></form></section><section class="panel"><h2>Saved sessions</h2>'+sessionList.map(function(s){return '<div class="session-row"><div><strong>'+esc(s.name)+'</strong><small>'+dateLabel(s.date)+'</small></div><button type="button" data-session="'+esc(s.id)+'" '+(s.id===state.id?'disabled':'')+'>'+(s.id===state.id?'Current':'Resume')+'</button></div>';}).join('')+'<button type="button" id="newSessionBtn" class="primary wide">New exercise session</button><button type="button" id="importBtn" class="wide">Restore session backup</button></section><section class="panel"><h2>How this app saves</h2><p>Sessions are stored on this browser and device. Export JSON backups before clearing browser data or moving to another device.</p><p>The projector is a separate read-only window on the same browser. It receives only released injects and the announced casualty totals. It does not share a live session over the internet.</p><p class="muted">Use one facilitator window. The controller console is not an authenticated role boundary: anyone with access to this browser can open it. Use fictional identifiers in exercise records.</p></section></div></div>';}

  function renderCoordination(){
    var phases=[['16:00','1 · Initial emergency notification','Full Emergency warning; ATC relays to ARFF Watch Room.'],['16:10','2 · Aircraft accident','Crash/aircraft accident activation; exact grid and runway clearance required.'],['After crash','3 · AEP activation','Notification cascade; RVP access; ARFF interim command.'],['After crash','4 · Rescue and firefighting','ARFF fire/rescue; formal transfer to the designated Incident Commander on arrival.'],['16:18','5 · Casualty management','Medical-led priorities; CCA → TA → CCS; 22 red of 110 POB.'],['16:20','6 · AEMC coordination','Gold strategic coordination; responding agency representative; Silver MCP joint working.'],['16:30 onward','7 · Accountability and family assistance','Reconcile manifest, patient, SRC and CRC records; FRRC and reunion support.'],['17:15','8 · Scene security and recovery','Police investigation and cordons; documented hazard/scene handover.'],['17:45','9 · Emergency termination','AEMC Chairperson, in coordination with the IC; demonstrate safe completion first.']];
    var roles=[['ATC / ARFF Watch Room','Emergency classification, alarm, message relay and notification protocols.','Ch. 13–14'],['ARFF','Initial incident command; fire/rescue; establish MCP, TA and CCA; formal command transfer to Incident Commander.','§8.3.1; §14.4'],['Designated Incident Commander','Assume overall on-scene command after handover; announce IC/MCP, agree tactics, allocate tasks, request AEMC support and maintain records.','§8.3.1; §14.4'],['Airport Manager / AEMC','Airport Manager or designee chairs Gold strategic coordination; resource support and joint decisions.','§8.2.1'],['Medical Coordinator / Hanimaadhoo Health Centre','Take medical/triage coordination, confirm priorities and document transfers; escalate surge to Kulhudhuffushi Regional Hospital.','§11.3–11.6; §14.4'],['Aviation Security Command (AVSECOM)','RVP coordinator; confirm IC clearance and record responding personnel and vehicles.','§11.14; §14.4'],['Police','Cordons, traffic, scene security, investigation and DVI; security of reception facilities.','§7.1; §14.4'],['Ramp Services','Staging/GSE readiness and initial establishment of CCS before formal handover to ARFF.','§11.6; §11.12'],['Passenger Services / airline','Passenger reception, crew reception, family support and manifest information; Police provides security.','§11.7–11.10'],['Agency AEMC representative','Strategic liaison; coordinate response/recovery resources and transport requirements; maintain comprehensive logs.','§14.4']];
    return heading('APPROVED HAQ AEP / EDITION 2','Command & facilities','Primary reference: issued 09 Nov 2025, effective 15 Nov 2025 · O2-MNL/2025/25.')+'<div class="note-box"><strong>HAQ command rule:</strong> ARFF holds initial incident command until the designated Incident Commander takes over. Conduct a face-to-face situation briefing and communicate the transfer time to the AEMC and responders. Gold = AEMC; Silver = MCP; Bronze = operational sectors. (§8.1–8.3.1)</div><div class="grid-two"><div class="stack"><section class="panel"><h2>Nine-phase discussion guide</h2><p class="muted">The HDK reference structure is adapted to HAQ. Times are exercise cues, not AEP response-time standards. Phases can overlap.</p><div class="table-wrap"><table><thead><tr><th>Scenario cue</th><th>Phase</th><th>Focus</th></tr></thead><tbody>'+phases.map(function(p){return '<tr>'+p.map(function(v){return '<td>'+esc(v)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div></section><section class="panel"><h2>Agency responsibilities</h2><div class="table-wrap"><table><thead><tr><th>Appointment / agency</th><th>Discussion responsibility</th><th>AEP reference</th></tr></thead><tbody>'+roles.map(function(r){return '<tr>'+r.map(function(v){return '<td>'+esc(v)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div></section><section class="panel"><h2>Facility activation board</h2><p class="muted">Record the appointment and validated location before marking a facility established. AEP nominated arrangements are shown below as reference, not live availability. Confirm them before entering a validated location; incident-area positions depend on hazards. These are exercise records, not live status.</p>'+state.facilities.map(function(f,i){return '<div class="review-card"><h3>'+esc(f.name)+'</h3><div class="form-grid"><label>Responsible appointment<input data-facility="'+i+'" data-field="owner" maxlength="120" value="'+esc(f.owner)+'"></label><label>Validated location<input data-facility="'+i+'" data-field="location" maxlength="160" value="'+esc(f.location)+'"></label><label class="full">Status<select data-facility="'+i+'" data-field="status">'+options(['Not established','Planned','Established','Closed'],f.status)+'</select></label></div></div>';}).join('')+'</section></div><div class="stack"><section class="panel"><h2>Command transfer record</h2><p class="muted">§8.3.1.1–8.3.1.2: ARFF → designated Incident Commander. No arrival time is assumed. Record the simulated transfer when the team agrees it has occurred.</p>'+state.commandTransfers.map(function(t){return '<div class="review-card"><strong>'+esc(t.scenario)+' MVT</strong><p>'+esc(t.from)+' → '+esc(t.to)+'</p><p>'+esc(t.brief)+'</p></div>';}).join('')+'<form id="transferCommandForm"><label>Outgoing commander / appointment<input name="from" required maxlength="120" placeholder="ARFF interim commander"></label><label>Incoming commander / appointment<input name="to" required maxlength="120" placeholder="Designated Incident Commander"></label><label>Face-to-face briefing: situation, hazards, tasks, resources<textarea name="brief" required maxlength="3000"></textarea></label><label><input name="announced" type="checkbox" required>Transfer time and command change communicated to AEMC and responders</label><button class="primary wide">Record command transfer</button></form></section><section class="panel"><h2>HAQ terminology & casualty flow</h2><p><strong>CCA:</strong> initial casualty collection and stabilisation after evacuation from the hot zone.</p><p><strong>TA:</strong> triage; red P1, yellow P2, green P3, black P4/deceased. Medical Coordinator takes over from initial ARFF management.</p><p><strong>CCS:</strong> registration, treatment, classification and dispatch. Ramp initially establishes it, then formally hands it to ARFF working with medical teams.</p><p><strong>SAA / SRC:</strong> assessed survivors may move from assembly to passenger reception. Surviving crew use CRC. Families use FRRC before controlled reunion.</p><p class="muted">§11.3–11.10. Minor/green status does not mean unassessed or automatically cleared.</p></section><section class="panel"><h2>Activation & termination</h2><p>At 16:00 use the Full Emergency discussion (Ch. 13). At 16:10 escalate to Aircraft Accident / Crash (Ch. 14). ATC and ARFF Watch Room relay the alert and activation protocols. External responders report to the RVP.</p><p>The AEP activation message calls for aircraft type, runway/grid, POB, runway entry clearance/standby and dangerous-goods information (§14.2). Fuel and DG details remain unknown until EXCON supplies them.</p><p>AEMC Chairperson declares accident-phase termination after coordination with the IC and confirmation that operations are complete and conditions safe (§14.5). Ending this tabletop app does not declare a real emergency terminated.</p></section><section class="panel"><h2>Source adaptation</h2><p><strong>Primary:</strong> user-supplied HAQ Airport Emergency Plan, Edition 2, effective 15 November 2025. Relevant chapters: 7–11, 13–14 and Appendix 1.</p><p><strong>Supporting:</strong> HDK Emergency Exercise 2026.pptx (34 slides) and matching HTML. Used for the nine-phase teaching structure, RVP/staging, logging, facilities and hotwash.</p><p>The HDK sources describe Kulhudhuffushi, 74 POB and a full-scale exercise. HAQ command arrangements and AEMC terminology take precedence here. The user’s A320, 110 POB, 16:00 call and 22 red casualties take precedence over source scenario details.</p><p class="muted">Reference PDFs/decks, contact directories and personal numbers are not embedded in the app. Confirm current revisions with the document controller. NO DUFF is taken from the HDK exercise convention and must be briefed locally for this tabletop.</p></section></div></div>';
  }

  function render() {
    document.querySelectorAll('[data-view]').forEach(function(b){b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    var views={control:renderControl,casualties:renderCasualties,resources:renderResources,decisions:renderDecisions,review:renderReview,setup:renderSetup,coordination:renderCoordination};
    $('pageContent').innerHTML=(state.pausedForSafety?'<div class="end-banner" role="alert">NO DUFF · Play paused. Follow real emergency arrangements. <button type="button" id="resumeSafetyBtn">EXCON: resume exercise</button></div>':'')+views[view]();bindView();updateClock();
  }
  function go(next){view=next;render();$('workspace').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
  function releaseNext(){
    if(state.ended||state.pausedForSafety||state.released.length>=S.injects.length)return;
    var i=state.released.length,inj=S.injects[i],ms=Math.max(elapsed(),inj.at*60000);state.elapsed=ms;state.anchor=state.running?Date.now():null;
    state.released.push({index:i,releasedAt:now(),scenario:scenarioTime(ms)});selectedInject=null;audit('Inject released',inj.title);save();render();toast('Released: '+inj.title);
  }
  function bindView(){
    if($('resumeSafetyBtn'))$('resumeSafetyBtn').onclick=function(){confirmAction('Resume exercise play?','EXCON must confirm it is appropriate to resume. The clock remains paused until you start it.',function(){state.pausedForSafety=false;audit('Safety pause','EXCON resumed exercise');save();render();});};
    if($('playBtn'))$('playBtn').onclick=function(){if(state.ended||state.pausedForSafety)return;if(state.running)pause();else{state.anchor=Date.now();state.running=true;}audit('Clock',state.running?'Started':'Paused');save();render();};
    if($('resetExerciseBtn'))$('resetExerciseBtn').onclick=function(){confirmAction('Reset the whole exercise?','This clears this session’s released injects, casualty movements, decisions, resources, command transfers, facility records, assessments and review actions. The timer returns to 16:00, paused at 1×. Session name, date and facilitator are kept. Export a backup first if you need the current records.',function(){var previous=state;state=fresh(previous.name,previous.date,previous.facilitator);state.id=previous.id;state.revision=previous.revision;selectedInject=null;categoryFilter="";patientSearch="";audit('Exercise reset','Current session restarted from the beginning');save();go('control');toast('Exercise reset. Ready to begin at 16:00.');});};
    if($('advanceBtn'))$('advanceBtn').onclick=function(){if(state.ended||state.pausedForSafety)return;state.elapsed=elapsed()+60000;state.anchor=state.running?Date.now():null;audit('Clock','Advanced one minute');save();updateClock();};
    if($('speedSelect'))$('speedSelect').onchange=function(e){state.elapsed=elapsed();state.anchor=state.running?Date.now():null;state.speed=Number(e.target.value);audit('Clock','Speed '+state.speed+'x');save();};
    if($('nextBtn'))$('nextBtn').onclick=releaseNext;
    if($('endBtn'))$('endBtn').onclick=function(){confirmAction('End this exercise?','The clock will stop and no further injects can be released. You can continue updating review, patient and decision records.',function(){pause();state.ended=true;audit('Exercise ended','Debrief started');save();go('review');});};
    if($('categoryFilter'))$('categoryFilter').onchange=function(e){categoryFilter=e.target.value;$('patientRows').innerHTML=patientRows();};
    if($('patientSearch'))$('patientSearch').oninput=function(e){patientSearch=e.target.value;$('patientRows').innerHTML=patientRows();};
    if($('selectFilteredBtn'))$('selectFilteredBtn').onclick=function(){document.querySelectorAll('[name=patientPick]').forEach(function(c){c.checked=true;});};
    if($('bulkPatientBtn'))$('bulkPatientBtn').onclick=function(){patientDialog(Array.from(document.querySelectorAll('[name=patientPick]:checked')).map(function(c){return c.value;}));};
    if($('resourceForm'))$('resourceForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),quantity=Number(f.get('quantity')),capability=String(f.get('capability')).trim(),owner=String(f.get('owner')).trim();
      if(!capability||!owner||!Number.isInteger(quantity)||quantity<1||quantity>10000){$('resourceError').textContent='Enter a capability, responsible appointment and valid quantity.';return;}
      if(['Assigned','Available'].includes(f.get('status'))&&!f.has('confirmed')){$('resourceError').textContent='Confirm capability and availability before marking a resource available or assigned.';return;}
      var resource={id:f.get('id')||uid(),capability:capability,owner:owner,quantity:quantity,eta:f.get('eta'),status:f.get('status'),confirmed:f.has('confirmed'),notes:String(f.get('notes')).trim(),updatedAt:now()};
      var pos=state.resources.findIndex(function(r){return r.id===resource.id;});if(pos<0)state.resources.push(resource);else state.resources[pos]=resource;
      audit('Resource task',capability+' · '+resource.status);save();render();toast('Resource task saved.');};
    if($('decisionForm'))$('decisionForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),text=String(f.get('text')).trim(),owner=String(f.get('owner')).trim(),action=String(f.get('action')).trim();if(!text||!owner||!action){toast('Enter a decision, owner and next action.');return;}var last=state.released[state.released.length-1];state.decisions.push({id:uid(),at:now(),scenario:scenarioTime(elapsed()),text:text,owner:owner,action:action,due:f.get('due'),inject:last?S.injects[last.index].title:'',status:'Open'});audit('Decision',text);save();render();toast('Decision recorded.');};
    document.querySelectorAll('[data-score]').forEach(function(el){el.onchange=function(){state.review[Number(el.dataset.score)].score=Number(el.value);audit('Assessment',S.objectives[Number(el.dataset.score)][0]+' · '+el.value);save();var rated=state.review.filter(function(r){return r.score>=0;});$('reviewScore').textContent=rated.reduce(function(n,r){return n+r.score;},0)+' / 12';$('ratedCount').textContent=rated.length+' of 6 objectives assessed · 0 = not addressed; 1 = incomplete; 2 = clear, feasible decision with owner.';};});
    document.querySelectorAll('[data-evidence]').forEach(function(el){el.onchange=function(){state.review[Number(el.dataset.evidence)].evidence=el.value;audit('Review evidence',S.objectives[Number(el.dataset.evidence)][0]);save();};});
    if($('actionForm'))$('actionForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),text=String(f.get('text')).trim(),owner=String(f.get('owner')).trim();if(!text||!owner){toast('Enter an action and owner.');return;}state.actions.push({id:uid(),text:text,owner:owner,due:f.get('due'),status:'Open',at:now()});audit('Improvement action',text);save();render();};
    if($('settingsForm'))$('settingsForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),name=String(f.get('name')).trim();if(!name){toast('Enter an exercise name.');return;}state.name=name;state.date=f.get('date');state.facilitator=String(f.get('facilitator')).trim();audit('Session details','Updated');save();render();toast('Session details saved.');};
    if($('newSessionBtn'))$('newSessionBtn').onclick=openNewSession;
    if($('importBtn'))$('importBtn').onclick=function(){$('importFile').click();};
    if($('reviewExportBtn'))$('reviewExportBtn').onclick=function(){$('exportDialog').showModal();};
    if($('transferCommandForm'))$('transferCommandForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),from=String(f.get('from')).trim(),to=String(f.get('to')).trim(),brief=String(f.get('brief')).trim();if(!from||!to||!brief||!f.has('announced')){toast('Record both appointments, the briefing and announcement confirmation.');return;}state.commandTransfers.push({id:uid(),at:now(),scenario:scenarioTime(elapsed()),from:from,to:to,brief:brief,announced:true});audit('Command transfer',from+' → '+to+'; AEMC/responders informed');save();render();toast('Command transfer recorded.');};
    document.querySelectorAll('[data-facility]').forEach(function(el){el.onchange=function(){var f=state.facilities[Number(el.dataset.facility)],field=el.dataset.field,newValue=el.value.trim();if(field==='status'&&newValue==='Established'&&(!f.owner.trim()||!f.location.trim())){el.value=f.status;toast('Record a responsible appointment and validated location before establishing this facility.');return;}if(['owner','location'].includes(field)&&!newValue&&f.status==='Established'){el.value=f[field];toast('An established facility needs an owner and location.');return;}f[field]=newValue;audit('Facility',f.name+' · '+field+': '+newValue);save();};});
  }
  function updateClock(){if($('clockValue'))$('clockValue').textContent=scenarioTime(elapsed());if($('clockDetail')){$('clockDetail').textContent=S.durationMinutes+' min total session · '+(state.ended?'Ended':state.running?'Running at '+state.speed+'×':'Paused')+' · T+'+Math.floor(elapsed()/60000)+' min · manual inject release';}}

  document.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;
    if(b.dataset.close){$(b.dataset.close).close();return;}
    if(b.dataset.view){go(b.dataset.view);return;}
    if(b.dataset.goto){go(b.dataset.goto);return;}
    if(b.dataset.inject!==undefined){selectedInject=Number(b.dataset.inject);render();return;}
    if(b.dataset.patient){patientDialog([b.dataset.patient]);return;}
    if(b.dataset.resource){var r=state.resources.find(function(x){return x.id===b.dataset.resource;}),f=$('resourceForm');if(!r)return;Object.keys(r).forEach(function(k){if(f.elements[k]){if(k==='confirmed')f.elements[k].checked=r[k];else f.elements[k].value=r[k];}});$('resourceFormTitle').textContent='Edit resource task';f.elements.capability.focus();return;}
    if(b.dataset.decision){var d=state.decisions.find(function(x){return x.id===b.dataset.decision;});d.status=d.status==='Open'?'Closed':'Open';audit('Decision status',d.text+' · '+d.status);save();render();return;}
    if(b.dataset.action){var a=state.actions.find(function(x){return x.id===b.dataset.action;});a.status=a.status==='Open'?'Closed':'Open';audit('Improvement action status',a.text+' · '+a.status);save();render();return;}
    if(b.dataset.session){switchSession(b.dataset.session);return;}
  });
  function switchSession(id){var target=read(PREFIX+id,null);if(!target){toast('That session is unavailable.');return;}try{validate(target);}catch(_){toast('Session data is damaged. Restore a backup.');return;}pause();save();state=target;pause();selectedInject=null;categoryFilter='';patientSearch='';audit('Session resumed','Clock paused for facilitator');save();render();toast('Session resumed with clock paused.');}
  $('newSessionForm').onsubmit=function(e){e.preventDefault();var f=new FormData(e.target),name=String(f.get('name')).trim();if(!name)return;pause();save();state=fresh(name,f.get('date'),String(f.get('facilitator')).trim());selectedInject=null;categoryFilter='';patientSearch='';audit('Session created',name);save();$('newSessionDialog').close();go('control');toast('New exercise ready. Previous session retained.');};
  $('projectorBtn').onclick=function(){publish();var w=window.open('ttx-display.html','northern-response-projector');if(!w)toast('Allow pop-ups for this site to open the projector.');};
  $('noDuffBtn').onclick=function(){pause();state.pausedForSafety=true;audit('Safety pause','NO DUFF: exercise play paused');save();render();toast('NO DUFF. Exercise play paused. Follow actual emergency arrangements.');};
  $('exportBtn').onclick=function(){$('exportDialog').showModal();};
  function download(name,content,type){var url=URL.createObjectURL(new Blob([content],{type:type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}
  function backup(){var copy=JSON.parse(JSON.stringify(state));copy.elapsed=elapsed();copy.running=false;copy.anchor=null;return {format:'northern-response-ttx',version:1,exportedAt:now(),session:copy};}
  $('backupBtn').onclick=function(){download('northern-response-'+state.date+'-'+state.id.slice(0,8)+'.json',JSON.stringify(backup(),null,2),'application/json');toast('Session backup downloaded.');};
  function report(){
    function table(headers,rows){return '<table><thead><tr>'+headers.map(function(h){return '<th>'+esc(h)+'</th>';}).join('')+'</tr></thead><tbody>'+rows.map(function(row){return '<tr>'+row.map(function(cell){return '<td style="white-space:pre-wrap">'+esc(cell)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table>';}
    var body='<h1>Northern Response · After-action report</h1><p>EXERCISE ONLY · '+esc(state.name)+'<br>Hanimaadhoo International Airport · A320 · 110 persons on board<br>Date: '+esc(state.date)+' · Facilitator: '+esc(state.facilitator||'Not assigned')+'<br>Total planned session: '+S.durationMinutes+' minutes (including briefing and debrief)<br>Scenario time: '+scenarioTime(elapsed())+' MVT (UTC+5) · Status: '+(state.ended?'Ended':'In progress')+'<br>Exported: '+esc(now())+' (UTC audit time)</p><h2>Scenario and assumptions</h2><p>16:00 landing gear emergency call; assumed crash at 16:10 with left-engine fire. 22 red (20%), 33 yellow, 50 green and 5 deceased. Six trapped persons are included within red. Local capabilities, authority and availability require AEP validation. This report records an exercise discussion, not practical certification.</p><h2>Objective assessment</h2>'+table(['Objective','Score / 2','Evidence'],S.objectives.map(function(o,i){return [o[0],state.review[i].score<0?'Not assessed':state.review[i].score,state.review[i].evidence];}))+'<h2>Released injects</h2>'+table(['Scheduled MVT','Released scenario MVT','Message'],state.released.map(function(r){return [clockText(S.injects[r.index].at*60000),r.scenario,S.injects[r.index].message];}))+'<h2>Decisions</h2>'+table(['Scenario MVT','Decision','Owner','Next action','Review MVT','Status'],state.decisions.map(function(d){return [d.scenario,d.text,d.owner,d.action,d.due,d.status];}))+'<h2>Resource tasks</h2>'+table(['Capability','Quantity','Owner','Status','Confirmed','ETA MVT','Notes'],state.resources.map(function(r){return [r.capability,r.quantity,r.owner,r.status,r.confirmed?'Yes':'No',r.eta,r.notes];}))+'<h2>Patient register</h2><p>'+(isUnlocked()?'Medical assessment released.':'Assessment not released during play. The following is the controller patient register.')+'</p>'+table(['ID','Priority','Status','Location','Destination','Accepted','Transport','Notes'],state.patients.map(function(p){return [p.id,p.category,p.status,p.location,p.destination,p.accepted?'Yes':'No',p.transport,p.notes];}))+'<h2>Improvement actions</h2>'+table(['Action','Owner','Due date','Status'],state.actions.map(function(a){return [a.text,a.owner,a.due,a.status];}))+'<h2>Audit log</h2>'+table(['UTC timestamp','Scenario MVT','Type','Detail'],state.audit.map(function(a){return [a.at,a.scenario,a.type,a.detail];}));
    body+='<h2>Command transfers</h2>'+table(['UTC timestamp','Scenario MVT','From','To','Briefing'],state.commandTransfers.map(function(t){return [t.at,t.scenario,t.from,t.to,t.brief];}))+'<h2>Facilities</h2>'+table(['Facility','Status','Responsible appointment','Validated location'],state.facilities.map(function(f){return [f.name,f.status,f.owner,f.location];}))+'<h2>Reference adaptation</h2><p>HDK Emergency Exercise 2026.pptx (34 slides) and HDK Emergency Exercise 2026.html supplied by the user: nine-phase response structure, RVP/staging, AEMC liaison, survivor/family facilities, scene handover, NO DUFF pause and evidence logging. The references describe a Kulhudhuffushi full-scale exercise with 74 POB. This app adapts their structure to a Hanimaadhoo tabletop with 110 POB and a 16:00 start. Their draft timings and local arrangements are not adopted as verified Hanimaadhoo facts. Primary operational reference: HAQ Airport Emergency Plan, Edition 2, effective 15 Nov 2025, Chapters 7–11, 13–14 and Appendix 1. ARFF initial command transfers to the designated Incident Commander; Gold coordination is through the AEMC.</p>';
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northern Response AAR</title><style>body{font:14px/1.6 Segoe UI,Arial,sans-serif;color:#17212a;margin:35px auto;max-width:1150px;padding:0 20px}h1{font-size:28px}h2{margin-top:30px;font-size:20px}table{border-collapse:collapse;width:100%;font-size:11px}td,th{text-align:left;vertical-align:top;border:1px solid #c9d1d7;padding:8px}th{background:#edf1f3}p{color:#42505a}tr{break-inside:avoid}@media print{body{margin:0;padding:0}h2{break-after:avoid}}</style></head><body>'+body+'</body></html>';
  }
  $('reportBtn').onclick=function(){download('northern-response-AAR-'+state.date+'.html',report(),'text/html');toast('Report downloaded. Open it to print or save as PDF.');};

  // Reject malformed backups before adopting any fields. IDs are allowlisted by format.
  function validate(s){
    function check(ok){if(!ok)throw new Error('Invalid or incompatible session backup.');}
    function str(v,max){return typeof v==='string'&&v.length<=max;}
    function iso(v){return str(v,40)&&Number.isFinite(Date.parse(v));}
    function time(v){return v===''||(/^\d{2}:\d{2}$/.test(v)&&Number(v.slice(0,2))<24&&Number(v.slice(3))<60);}
    function list(v,max){return Array.isArray(v)&&v.length<=max;}
    function unique(v){return v.every(function(x){return x&&str(x.id,100)&&/^[a-zA-Z0-9-]+$/.test(x.id);})&&new Set(v.map(function(x){return x.id;})).size===v.length;}
    check(s&&typeof s==='object'&&s.schema===1&&s.scenarioId===S.id&&str(s.id,100)&&/^[a-zA-Z0-9-]+$/.test(s.id));
    check(str(s.name,100)&&s.name.trim()&&str(s.facilitator,100)&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&iso(s.createdAt)&&iso(s.updatedAt));
    check(Number.isFinite(s.elapsed)&&s.elapsed>=0&&s.elapsed<=7*24*3600000&&[1,2,5,10].includes(s.speed)&&typeof s.running==='boolean'&&typeof s.ended==='boolean'&&(!s.running||Number.isFinite(s.anchor))&&Number.isInteger(s.revision));
    check(list(s.released,S.injects.length));s.released.forEach(function(r,i){check(r&&r.index===i&&iso(r.releasedAt)&&str(r.scenario,20));});
    var expected=fresh('x','2000-01-01','').patients;
    check(list(s.patients,110)&&s.patients.length===110&&unique(s.patients));s.patients.forEach(function(p,i){check(p.id===expected[i].id&&p.category===expected[i].category&&patientStatuses.includes(p.status)&&str(p.location,120)&&str(p.destination,120)&&str(p.transport,100)&&str(p.notes,2000)&&typeof p.accepted==='boolean');check(!['In transfer','Handed over'].includes(p.status)||(p.accepted&&p.destination.trim()&&p.transport.trim()));check(p.category!=='Deceased'||!['Treatment','In transfer','Handed over'].includes(p.status));check(p.category==='Deceased'||p.status!=='Deceased holding');});
    check(list(s.decisions,5000)&&unique(s.decisions));s.decisions.forEach(function(d){check(str(d.id,100)&&str(d.text,4000)&&str(d.owner,120)&&str(d.action,2000)&&time(d.due)&&str(d.scenario,20)&&str(d.inject,200)&&iso(d.at)&&['Open','Closed'].includes(d.status));});
    check(list(s.resources,5000)&&unique(s.resources));s.resources.forEach(function(r){check(str(r.id,100)&&str(r.capability,120)&&str(r.owner,120)&&Number.isInteger(r.quantity)&&r.quantity>0&&r.quantity<=10000&&time(r.eta)&&str(r.notes,3000)&&['Requested','Available','Assigned','Released','Unavailable'].includes(r.status)&&typeof r.confirmed==='boolean');check(!['Available','Assigned'].includes(r.status)||r.confirmed);});
    check(list(s.actions,5000)&&unique(s.actions));s.actions.forEach(function(a){check(str(a.id,100)&&str(a.text,3000)&&str(a.owner,120)&&/^\d{4}-\d{2}-\d{2}$/.test(a.due)&&['Open','Closed'].includes(a.status)&&iso(a.at));});
    check(list(s.review,6)&&s.review.length===6);s.review.forEach(function(r){check([-1,0,1,2].includes(r.score)&&str(r.evidence,4000));});
    check(list(s.commandTransfers,1000)&&unique(s.commandTransfers));s.commandTransfers.forEach(function(t){check(iso(t.at)&&str(t.scenario,20)&&str(t.from,120)&&str(t.to,120)&&str(t.brief,3000)&&t.announced===true);});
    check(typeof s.pausedForSafety==='boolean'&&(!s.pausedForSafety||!s.running));
    check(list(s.facilities,facilityNames.length)&&s.facilities.length===facilityNames.length);s.facilities.forEach(function(f,i){check(f.name===facilityNames[i]&&['Not established','Planned','Established','Closed'].includes(f.status)&&str(f.owner,120)&&str(f.location,160));check(f.status!=='Established'||(f.owner.trim()&&f.location.trim()));});
    check(list(s.audit,50000));s.audit.forEach(function(a){check(iso(a.at)&&str(a.scenario,20)&&str(a.type,100)&&str(a.detail,20000));});
    return s;
  }
  $('importFile').onchange=async function(e){var file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024){toast('Backup too large. Maximum size is 8 MB.');return;}try{var parsed=JSON.parse(await file.text());if(parsed.format!=='northern-response-ttx'||parsed.version!==1)throw new Error('Choose a Northern Response session backup.');var imported=validate(parsed.session);confirmAction('Restore this session?',esc(imported.name)+' will be restored as a new session. Existing sessions are retained.',function(){pause();save();state=JSON.parse(JSON.stringify(imported));state.id=uid();state.elapsed=imported.elapsed;state.running=false;state.anchor=null;state.name=(state.name+' (restored)').slice(0,100);selectedInject=null;categoryFilter='';patientSearch='';audit('Backup restored','Imported as a separate session');save();go('control');toast('Backup restored with clock paused.');});}catch(err){toast(err.message||'Could not read that backup.');}};

  sessionList=read(INDEX,[]);if(!Array.isArray(sessionList))sessionList=[];
  sessionList=sessionList.filter(function(s){return s&&typeof s.id==='string'&&/^[a-zA-Z0-9-]+$/.test(s.id)&&typeof s.name==='string'&&typeof s.date==='string';});
  state=read(PREFIX+read(ACTIVE,''),null);
  try{validate(state);}catch(_){state=fresh('Northern Response — Hanimaadhoo',mvtDate(),'');audit('Session created','Initial exercise');}
  save();render();
  window.addEventListener('storage',function(e){if(e.key===PREFIX+state.id&&e.newValue){try{var incoming=validate(JSON.parse(e.newValue));if(incoming.revision>state.revision){state=incoming;selectedInject=null;render();toast('Updated from another facilitator window. Use one controller window.');}}catch(_){/* Never adopt damaged external state. */}}});
  window.addEventListener('pagehide',function(){if(state.running){state.elapsed=elapsed();state.anchor=Date.now();save();}});
  setInterval(function(){updateClock();publish();},1000);
  if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(function(){/* Local-file use and unsupported hosts still run the console. */});
})();
